select is((select cantidad from public.carga_vendedor where vendedor_id='20000000-0000-0000-0001-000000000004' and producto_id='40000000-0000-0000-0000-000000000001'),7,'Failed cancellation preserves seller load 7');
select is((select count(*) from public.auditoria),(select n from cancellation_audit_before),'Failed cancellation leaves audit unchanged');
select is((select anulado from public.despachos where id='61000000-0000-0000-0000-000000000005'),false,'Failed cancellation preserves active parent');

-- Independent return reversals also use OLD quantity/state, not edited NEW.
update public.stock_envases set cantidad=10 where sucursal_id='10000000-0000-0000-0000-000000000001' and tipo_empaque_id='30000000-0000-0000-0000-000000000001';
insert into public.devoluciones_envases(id,despacho_id,tipo_empaque_id,cantidad,creado_por) values('65000000-0000-0000-0000-000000000006','61000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000001',2,'20000000-0000-0000-0001-000000000001');
update public.devoluciones_envases set cantidad=20,estado='malo',anulado=true where id='65000000-0000-0000-0000-000000000006';
select is((select cantidad from public.stock_envases where sucursal_id='10000000-0000-0000-0000-000000000001' and tipo_empaque_id='30000000-0000-0000-0000-000000000001'),10,'Container return reversal uses OLD bueno/2 despite NEW malo/20');
insert into public.devoluciones_productos(id,despacho_id,producto_id,cantidad,creado_por) values('65000000-0000-0000-0000-000000000007','61000000-0000-0000-0000-000000000005','40000000-0000-0000-0000-000000000001',4,'20000000-0000-0000-0001-000000000001');
update public.devoluciones_productos set cantidad=20,anulado=true where id='65000000-0000-0000-0000-000000000007';
select is((select cantidad from public.stock_bodega where sucursal_id='10000000-0000-0000-0000-000000000001' and producto_id='40000000-0000-0000-0000-000000000001'),90,'Product return reversal uses OLD 4 despite NEW 20');
select throws_ok($q$update public.devoluciones_productos set anulado=false where id='65000000-0000-0000-0000-000000000007'$q$,'P0001','No se puede reactivar un movimiento anulado.','Product return reactivation rejected');
insert into public.devoluciones_productos(despacho_id,producto_id,cantidad,creado_por,anulado) values('61000000-0000-0000-0000-000000000005','40000000-0000-0000-0000-000000000001',2,'20000000-0000-0000-0001-000000000001',true);
select is((select cantidad from public.stock_bodega where sucursal_id='10000000-0000-0000-0000-000000000001' and producto_id='40000000-0000-0000-0000-000000000001'),90,'Already-annulled product return moves nothing');
insert into public.devoluciones_envases(despacho_id,tipo_empaque_id,cantidad,creado_por,anulado) values('61000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000001',2,'20000000-0000-0000-0001-000000000001',true);
select is((select cantidad from public.stock_envases where sucursal_id='10000000-0000-0000-0000-000000000001' and tipo_empaque_id='30000000-0000-0000-0000-000000000001'),10,'Already-annulled container return moves nothing');
select throws_ok($q$update public.producciones set anulado=false where id='62000000-0000-0000-0000-000000000003'$q$,'P0001','No se puede reactivar un movimiento anulado.','Production reactivation rejected');
update public.ventas set anulado=true where cliente_id='50000000-0000-0000-0000-000000000001' and total=3000;
select is((select cantidad from public.carga_vendedor where vendedor_id='20000000-0000-0000-0001-000000000004' and producto_id='40000000-0000-0000-0000-000000000001'),10,'Sale cancellation restores sold load once');
select throws_ok($q$update public.ventas set anulado=false where cliente_id='50000000-0000-0000-0000-000000000001' and total=3000$q$,'P0001','No se puede reactivar un movimiento anulado.','Sale reactivation rejected');
select throws_ok($q$insert into public.despacho_envases(despacho_id,tipo_empaque_id,cantidad) values('61000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000001',1)$q$,'P0001','El despacho solo admite envases de uso interno.','Dispatch packaging respects internal-use invariant');
select * from finish();
rollback;
